import sys, openpyxl
wb = openpyxl.load_workbook(sys.argv[1], data_only=False)
for ws in wb.worksheets:
    print(f"=== SHEET {ws.title} dims={ws.dimensions}")
    for row in ws.iter_rows():
        vals = [c.value for c in row]
        if any(v is not None for v in vals):
            print(" | ".join("" if v is None else str(v) for v in vals))
    # comments
    for row in ws.iter_rows():
        for c in row:
            if c.comment:
                print(f"COMMENT {c.coordinate}: {c.comment.text}")
EOF
