def sc_calc(design, motor_fla=None, verbose=True):
    """design: dict feeder -> (size, N); returns dict bus -> (sym kA, motor kA, total kA)"""
    if motor_fla is None: motor_fla = {'HM1':182.0, 'HE1':77.6}
    V = 480.0
    Zu = V**2/250e6; xr=12; Ru = Zu/math.sqrt(1+xr*xr); Zu_c = complex(Ru, Ru*xr)
    Zt = 0.0575*V**2/1000e3; xr=6.5; Rt = Zt/math.sqrt(1+xr*xr); Zt_c = complex(Rt, Rt*xr)
    L = {k: runs[k]['length'] for k in runs}
    def zc(tag):
        s, n = design[tag]; return zcable(s, L[tag], n)
    Z = {}
    Z['MSB'] = Zu_c + Zt_c + zc('MSB')
    for b in ['HM1','H1A','H2A','ATS-E','ATS-L']:
        Z[b] = Z['MSB'] + zc(b)
    Z['HE1'] = Z['ATS-E'] + zc('HE1')
    TX = {'T-1A':(112.5,4.2,2.0,'H1A','LP1A'), 'T-2A':(75,4.0,1.8,'H2A','LP2A'), 'T-C1':(45,3.6,1.5,'H1A','LC1'), 'T-E1':(45,3.6,1.5,'ATS-L','LE1')}
    for t,(kva,zp,xr,src,load) in TX.items():
        Zprim = Z[src] + zc(t)   # at 480 V
        ratio = (208/480)**2
        Ztx = zp/100*208**2/(kva*1000); R = Ztx/math.sqrt(1+xr*xr); Ztx_c = complex(R, R*xr)
        Z[load] = Zprim*ratio + Ztx_c + zc(load)
    # motor contributions
    mot = {b:0.0 for b in Z}
    mot['HM1'] += 4*motor_fla['HM1']; mot['MSB'] += 4*motor_fla['HM1']
    mot['HE1'] += 4*motor_fla['HE1']; mot['ATS-E'] += 4*motor_fla['HE1']; mot['MSB'] += 4*motor_fla['HE1']
    res = {}
    for b, z in Z.items():
        v = 208.0 if b in ('LP1A','LP2A','LC1','LE1') else 480.0
        I = v/(math.sqrt(3)*abs(z))/1000
        res[b] = (v, I, mot[b]/1000, I + mot[b]/1000)
    return res
