"""Convert a SpecsIntact .SEC file to an editable block list (Army tailoring, English units, notes removed).
Output lines: ID|TYPE|text"""
import sys, re
from lxml import etree
SECDIR = '/filesystem/final_batch4__electrical_task8_electrical_specs__blind/20_guide_specifications/UFGS_Division_26_SpecsIntact/'
def keep_tai(el):
    opt = el.get('OPT','')
    opts = [o.strip() for o in opt.split(',')]
    if 'NOT-ARMY' in opts: return False
    return 'ARMY' in opts
INLINE_DROP = {'MET','NTE','AST','NED','BRL','STS','HDR'}
def inline_text(el):
    """text of an element treated as inline content (children inline)."""
    out = []
    if el.text: out.append(el.text)
    for ch in el:
        tag = ch.tag if isinstance(ch.tag, str) else ''
        if tag in INLINE_DROP:
            pass
        elif tag == 'TAI':
            if keep_tai(ch): out.append(inline_text(ch))
        elif tag == 'BRK':
            out.append(' ')
        elif tag == 'NPR':
            pass
        else:
            out.append(inline_text(ch))
        if ch.tail: out.append(ch.tail)
    return ''.join(out)
def norm(s):
    s = s.replace('\r',' ').replace('\n',' ').replace('\t',' ')
    s = re.sub(r' {2,}', '  ', s)
    return s.strip()
class Walker:
    def __init__(self):
        self.blocks = []
    def emit(self, typ, text):
        self.blocks.append([typ, text])
    def loose(self, s):
        if s is None: return
        t = s.strip()
        if t:
            # emit bracket/dash fragments as separate BRK blocks
            for piece in re.findall(r'\[|\]|[^\[\]\s][^\[\]]*', t):
                p = piece.strip()
                if p: self.emit('BRK', p)
    def walk_children(self, el, level):
        self.loose(el.text)
        for ch in el:
            self.walk(ch, level)
            self.loose(ch.tail)
    def walk(self, el, level):
        tag = el.tag if isinstance(el.tag, str) else ''
        if tag in ('NTE','HDR','AST','BRK','BRL','MTA','NED','STS'): return
        if tag == 'TAI':
            if keep_tai(el): self.walk_children(el, level)
            return
        if tag == 'SCN': self.emit('SCN', norm(inline_text(el))); return
        if tag == 'STL': self.emit('STL', norm(inline_text(el))); return
        if tag == 'DTE': self.emit('DTE', norm(inline_text(el))); return
        if tag == 'END': self.emit('END', ''); return
        if tag == 'PRT':
            ttl = el.find('TTL')
            self.emit('PRT', norm(inline_text(ttl)) if ttl is not None else '')
            self.loose(ttl.tail if ttl is not None else None)
            for ch in el:
                if ch is ttl: continue
                self.walk(ch, 1); self.loose(ch.tail)
            return
        if tag == 'SPT':
            ttl = el.find('TTL')
            self.emit('SPT%d' % level, norm(inline_text(ttl)) if ttl is not None else '')
            if ttl is not None: self.loose(ttl.tail)
            for ch in el:
                if ch is ttl: continue
                self.walk(ch, level+1); self.loose(ch.tail)
            return
        if tag == 'TXT': self.emit('TXT', norm(inline_text(el))); return
        if tag == 'OLG': self.walk_children(el, level); return
        if tag == 'OLI':
            lv = el.get('LEVEL','1'); self.emit('OL%s' % lv, norm(inline_text(el))); return
        if tag == 'LST': self.emit('LST', norm(inline_text(el))); return
        if tag == 'ITM': self.emit('ITM', norm(inline_text(el))); return
        if tag == 'REF':
            cur = None
            self.loose(el.text)
            for ch in el:
                t = ch.tag
                if t == 'ORG': self.emit('ORG', norm(inline_text(ch)))
                elif t == 'RID': cur = norm(inline_text(ch))
                elif t == 'RTL':
                    self.emit('REF', (cur or '') + ' :: ' + norm(inline_text(ch))); cur = None
                elif t == 'TAI':
                    if keep_tai(ch):
                        # rare: tailored reference entries
                        for c2 in ch:
                            if c2.tag == 'RID': cur = norm(inline_text(c2))
                            elif c2.tag == 'RTL': self.emit('REF', (cur or '') + ' :: ' + norm(inline_text(c2))); cur=None
                            elif c2.tag == 'ORG': self.emit('ORG', norm(inline_text(c2)))
                self.loose(ch.tail) if ch.tag not in ('BRK',) else None
            return
        if tag == 'TAB':
            for row in el.iter('ROW'):
                cells = []
                for cel in row.findall('CEL'):
                    cells.append(norm(inline_text(cel)))
                if any(cells): self.emit('TROW', ' || '.join(cells))
            return
        if tag in ('ITM','TTL'):
            self.emit('TXT', norm(inline_text(el))); return
        # unknown block-level: treat as inline text
        txt = norm(inline_text(el))
        if txt: self.emit('X_'+tag, txt)
def convert(num):
    raw = open(SECDIR + num + '.SEC', 'rb').read().decode('cp1252')
    raw = re.sub(r'^<\?xml[^>]*\?>', '', raw)
    parser = etree.XMLParser(recover=True, huge_tree=True)
    root = etree.fromstring(raw.encode('utf-8'), parser)
    w = Walker()
    for ch in root:
        w.walk(ch, 1); w.loose(ch.tail)
    return w.blocks
if __name__ == '__main__':
    num = sys.argv[1]
    blocks = convert(num)
    out = open('/tmp/work/specs/%s.blk' % num.replace(' ','_'), 'w')
    for i,(t,x) in enumerate(blocks):
        out.write('B%04d|%s|%s\n' % (i+1, t, x))
    out.close()
    from collections import Counter
    print(num, len(blocks), Counter(t for t,_ in blocks))
