"""Render an edited block file to a .docx with literal numbering."""
import sys, re, zipfile, html
from xml.sax.saxutils import escape
def esc(s):
    s = escape(s)
    return s
def para(text, bold=False, indent=0, center=False, keep=False, size=None):
    ppr = []
    if center: ppr.append('<w:jc w:val="center"/>')
    if indent: ppr.append('<w:ind w:left="%d"/>' % indent)
    ppr.append('<w:spacing w:after="120"/>')
    rpr = []
    if bold: rpr.append('<w:b/>')
    if size: rpr.append('<w:sz w:val="%d"/>' % size)
    rpr_s = '<w:rPr><w:rFonts w:ascii="Courier New" w:hAnsi="Courier New" w:cs="Courier New"/>%s</w:rPr>' % ''.join(rpr)
    return '<w:p><w:pPr>%s</w:pPr><w:r>%s<w:t xml:space="preserve">%s</w:t></w:r></w:p>' % (''.join(ppr), rpr_s, esc(text))
def table(rows):
    ncol = max(len(r) for r in rows)
    out = ['<w:tbl><w:tblPr><w:tblStyle w:val="TableGrid"/><w:tblW w:w="0" w:type="auto"/><w:tblBorders>'
           '<w:top w:val="single" w:sz="4" w:space="0" w:color="000000"/><w:left w:val="single" w:sz="4" w:space="0" w:color="000000"/>'
           '<w:bottom w:val="single" w:sz="4" w:space="0" w:color="000000"/><w:right w:val="single" w:sz="4" w:space="0" w:color="000000"/>'
           '<w:insideH w:val="single" w:sz="4" w:space="0" w:color="000000"/><w:insideV w:val="single" w:sz="4" w:space="0" w:color="000000"/>'
           '</w:tblBorders></w:tblPr><w:tblGrid>']
    for _ in range(ncol): out.append('<w:gridCol w:w="%d"/>' % (9000//ncol))
    out.append('</w:tblGrid>')
    for r in rows:
        out.append('<w:tr>')
        for i in range(ncol):
            c = r[i] if i < len(r) else ''
            out.append('<w:tc><w:tcPr><w:tcW w:w="%d" w:type="dxa"/></w:tcPr>%s</w:tc>' % (9000//ncol, para(c, size=18)))
        out.append('</w:tr>')
    out.append('</w:tbl>')
    return ''.join(out)
LETTERS = 'abcdefghijklmnopqrstuvwxyz'
def alpha(n):
    s = ''
    while True:
        s = LETTERS[n % 26] + s
        n = n//26 - 1
        if n < 0: break
    return s
def render(blocks):
    """blocks: list of (type, text). returns list of xml chunks and list of plain text paragraphs"""
    body = []; plain = []
    part = 0; sp = [0]*8
    ol = [0]*5
    pending_rows = []
    def flush_rows():
        nonlocal pending_rows
        if pending_rows:
            body.append(table(pending_rows)); 
            for r in pending_rows: plain.extend(r)
            pending_rows = []
    def add(text, **kw):
        body.append(para(text, **kw)); plain.append(text)
    for typ, text in blocks:
        if typ != 'TROW': flush_rows()
        if not typ.startswith('OL') and typ not in ('LST',):
            ol = [0]*5
        if typ == 'SCN': add(text, bold=True, center=True)
        elif typ == 'STL': add(text, bold=True, center=True)
        elif typ == 'DTE': add(text, center=True)
        elif typ == 'PRT':
            part += 1; sp = [0]*8
            m = re.match(r'PART\s+(\d+)\s+(.*)', text)
            title = m.group(2).strip() if m else text
            add('PART %d   %s' % (part, title.upper()), bold=True)
        elif typ.startswith('SPT'):
            lv = int(typ[3:])
            sp[lv] += 1
            for k in range(lv+1, 8): sp[k] = 0
            num = '.'.join([str(part)] + [str(sp[k]) for k in range(1, lv+1)])
            title = text.upper() if lv == 1 else text
            add('%s %s' % (num, title), bold=(lv==1))
        elif typ.startswith('OL'):
            lv = int(typ[2:])
            ol[lv] += 1
            for k in range(lv+1, 5): ol[k] = 0
            if lv == 1: mk = '%s.' % alpha(ol[1]-1)
            elif lv == 2: mk = '(%d)' % ol[2]
            elif lv == 3: mk = '(%s)' % alpha(ol[3]-1)
            else: mk = '%d.' % ol[4]
            add('%s %s' % (mk, text), indent=360*lv)
        elif typ == 'TXT': add(text)
        elif typ == 'ORG': add(text, bold=True)
        elif typ == 'REF':
            rid, _, rtl = text.partition(' :: ')
            add('%s    %s' % (rid.strip(), rtl.strip()), indent=360)
        elif typ == 'LST': add(text, indent=360)
        elif typ == 'ITM': add(text, indent=720)
        elif typ == 'TROW': pending_rows.append([c.strip() for c in text.split('||')])
        elif typ == 'END': add('-- End of Section --', center=True)
        elif typ == 'BRK': raise ValueError('unresolved bracket block: %r' % text)
        else: raise ValueError('unknown block type %s: %s' % (typ, text))
    flush_rows()
    return body, plain
CT = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
      '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
      '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
      '<Default Extension="xml" ContentType="application/xml"/>'
      '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
      '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>'
      '</Types>')
RELS = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
        '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>'
        '</Relationships>')
def core(title):
    return ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" '
            'xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" '
            'xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
            '<dc:title>%s</dc:title><dc:creator>Harlan Sato Engineers LLC</dc:creator></cp:coreProperties>' % esc(title))
def write_docx(path, blocks, title):
    body, plain = render(blocks)
    doc = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
           '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
           '<w:body>%s<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720" w:gutter="0"/></w:sectPr></w:body></w:document>') % ''.join(body)
    with zipfile.ZipFile(path, 'w', zipfile.ZIP_DEFLATED) as z:
        z.writestr('[Content_Types].xml', CT)
        z.writestr('_rels/.rels', RELS)
        z.writestr('word/document.xml', doc)
        z.writestr('docProps/core.xml', core(title))
    return plain
def read_blocks(path):
    out = []
    for line in open(path, encoding='utf-8'):
        line = line.rstrip('\n')
        if not line.strip(): continue
        bid, typ, text = line.split('|', 2)
        out.append((bid, typ, text))
    return out
