import sys, re, importlib.util, json
sys.path.insert(0, '/tmp/work')
from blocks2docx import read_blocks, write_docx
def apply(num, patches, strict=True):
    blk = read_blocks('/tmp/work/specs/%s.blk' % num.replace(' ','_'))
    ids = [b[0] for b in blk]
    pos = {b: i for i, b in enumerate(ids)}
    typ = {b[0]: b[1] for b in blk}
    txt = {b[0]: b[2] for b in blk}
    dele = set(); ins_after = {}; ins_before = {}
    errs = []
    for p in patches:
        op = p[0]
        if op == 'del':
            a = p[1]; b = p[2] if len(p) > 2 else p[1]
            if a not in pos or b not in pos: errs.append('bad del %s %s' % (a, b)); continue
            for i in range(pos[a], pos[b]+1): dele.add(ids[i])
        elif op == 'set':
            if p[1] not in txt: errs.append('bad set %s' % p[1]); continue
            txt[p[1]] = p[2]
            if len(p) > 3: typ[p[1]] = p[3]
        elif op == 'sub':
            i, old, new = p[1], p[2], p[3]
            if i not in txt or old not in txt[i]: errs.append('sub miss %s: %r' % (i, old[:80])); continue
            cnt = p[4] if len(p) > 4 else 1
            txt[i] = txt[i].replace(old, new, cnt)
        elif op == 'typ':
            typ[p[1]] = p[2]
        elif op == 'ins':   # insert after
            ins_after.setdefault(p[1], []).append((p[2], p[3]))
        elif op == 'insb':  # insert before
            ins_before.setdefault(p[1], []).append((p[2], p[3]))
        elif op == 'gsub':  # global substring replace in all blocks
            for k in txt: txt[k] = txt[k].replace(p[1], p[2])
        else: errs.append('bad op %r' % (p,))
    out = []
    for b in ids:
        for t, x in ins_before.get(b, []): out.append((b+'+', t, x))
        if b not in dele: out.append((b, typ[b], txt[b]))
        for t, x in ins_after.get(b, []): out.append((b+'+', t, x))
    # checks
    for b, t, x in out:
        if t == 'BRK': errs.append('BRK left %s %r' % (b, x))
        if '[' in x or ']' in x: errs.append('bracket left %s: %s' % (b, x[:160]))
        if '_____' in x or '____' in x: errs.append('blank left %s' % b)
    return out, errs
def build(num, title, patches, outdir='/tmp/work/out/specs', strict=True):
    import os
    os.makedirs(outdir, exist_ok=True)
    out, errs = apply(num, patches)
    for e in errs: print('  !!', e)
    blocks = [(t, re.sub(r'\s{2,}', ' ', x).strip()) for b, t, x in out]
    # final cosmetic: collapse spaces
    path = os.path.join(outdir, '%s %s.docx' % (num, title.replace('/', '-')))
    if errs and strict:
        print('  NOT WRITTEN (errors)'); return None, errs
    plain = write_docx(path, blocks, 'SECTION %s %s' % (num, title))
    return path, errs
def show(num, a=None, b=None, patches=None, width=400):
    if patches is not None:
        out, errs = apply(num, patches)
    else:
        out = read_blocks('/tmp/work/specs/%s.blk' % num.replace(' ','_')); errs = []
    on = a is None
    for bid, t, x in out:
        if bid.rstrip('+') == a: on = True
        if on: print('%s|%s|%s' % (bid, t, x[:width]))
        if b is not None and bid.rstrip('+') == b: on = False
    return errs
